// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testFuzz_property(address caller, uint256 amount, address recipient) public {
        vm.assume(caller != address(this));
        vm.assume(recipient != address(0));
        vm.assume(caller != recipient);
        amount = bound(amount, 0, 100 ether);
        vm.deal(caller, amount);
        vm.deal(address(c), amount);
        uint256 beforeBal = address(c).balance;
        bool ok = true;
        vm.prank(caller);
        try c.withdrawAll(recipient) {} catch { ok = false; }
        assertTrue(!ok);
    }
}
